  ));
  ELSE
    PERFORM __mj."spUpdateAIModelCost"(p_Comments := p_Comments_27df8eb1f2cc, p_CacheReadPricePerUnit := p_CacheReadPricePerUnit_27df8eb1f2cc, p_ID := p_ID_27df8eb1f2cc);
  END IF;
END $mj$;

